pub fn find_controller(controller_id: u16) -> Option<&'static WaysideProfile> {
    WAYSIDE_PROFILES
        .iter()
        .find(|profile| profile.controller_id == controller_id)
}

pub fn controller_bias(controller_id: u16) -> u32 {
    find_controller(controller_id)
        .map(|p| p.feature_mask ^ p.battery_minutes as u32)
        .unwrap_or(controller_id as u32)
}
